using UnityEngine;

[RequireComponent(typeof(Rigidbody))]
public class PlayerMovement : MonoBehaviour
{
    [Header("Movement Settings")]
    [SerializeField] private float moveSpeed = 5f;

    [Header("Dash Settings")]
    [SerializeField] private float dashSpeed = 20f;
    [SerializeField] private float dashDuration = 0.2f;
    [SerializeField] private float dashCooldown = 1f;

    private Rigidbody rb;
    private Vector3 moveDirection;

    private bool isDashing;
    private float lastDashTime;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        rb.freezeRotation = true; // Prevents the Rigidbody from rotating due to physics forces
    }

    private void Update()
    {
        HandleInput();
        HandleDash();
    }

    private void FixedUpdate()
    {
        if (!isDashing)
        {
            HandleMovement();
        }
    }

    private void HandleInput()
    {
        float moveX = Input.GetAxisRaw("Horizontal");
        float moveZ = Input.GetAxisRaw("Vertical");

        moveDirection = new Vector3(moveX, 0f, moveZ).normalized;
    }

    private void HandleMovement()
    {
        rb.velocity = moveDirection * moveSpeed;
    }

    private void HandleDash()
    {
        if (Input.GetKeyDown(KeyCode.Space) && Time.time >= lastDashTime + dashCooldown)
        {
            StartDash();
        }
    }

    private void StartDash()
    {
        isDashing = true;
        lastDashTime = Time.time;

        Vector3 dashDirection = moveDirection;
        // If the player is not moving, dash in the direction they are facing
        if (dashDirection == Vector3.zero)
        {
            dashDirection = transform.forward;
        }

        rb.velocity = dashDirection * dashSpeed;

        // Stop the dash after the specified duration
        Invoke(nameof(StopDash), dashDuration);
    }

    private void StopDash()
    {
        isDashing = false;
        // Reset velocity to avoid abrupt stops if there's no movement input
        if (rb.velocity.magnitude > moveSpeed)
        {
            rb.velocity = Vector3.zero;
        }
    }
}

