using UnityEngine;

public class PlayerMovement
{
    // Movement Settings
    private readonly float _moveSpeed = 7f;

    // Dash Settings
    private readonly float _dashSpeed = 25f;
    private readonly float _dashDuration = 0.15f;
    private readonly float _dashCooldown = 1f;

    // References
    private readonly CharacterController _controller;
    private readonly Transform _transform;

    // State
    private Vector3 _moveDirection;
    private float _dashCooldownTimer;
    private float _dashTimer;
    private bool _isDashing;
    private Vector3 _dashDirection;


    public PlayerMovement(CharacterController controller)
    {
        _controller = controller;
        _transform = controller.transform;
    }

    public void Tick()
    {
        HandleInput();
        HandleDash();

        if (_isDashing)
        {
            _controller.Move(_dashDirection * _dashSpeed * Time.deltaTime);
        }
        else
        {
            HandleMovement();
        }
    }

    private void HandleInput()
    {
        // Do not process movement input if dashing
        if (_isDashing) return;

        float moveX = Input.GetAxisRaw("Horizontal");
        float moveZ = Input.GetAxisRaw("Vertical");

        _moveDirection = new Vector3(moveX, 0f, moveZ).normalized;
    }

    private void HandleMovement()
    {
        _controller.Move(_moveDirection * _moveSpeed * Time.deltaTime);
    }

    private void HandleDash()
    {
        // Update timers
        if (_dashCooldownTimer > 0)
        {
            _dashCooldownTimer -= Time.deltaTime;
        }
        if (_dashTimer > 0)
        {
            _dashTimer -= Time.deltaTime;
            if (_dashTimer <= 0)
            {
                _isDashing = false;
            }
        }

        // Check for dash input
        if (Input.GetKeyDown(KeyCode.Space) && _dashCooldownTimer <= 0)
        {
            StartDash();
        }
    }

    private void StartDash()
    {
        _isDashing = true;
        _dashCooldownTimer = _dashCooldown;
        _dashTimer = _dashDuration;

        // If player is moving, dash in that direction
        if (_moveDirection.sqrMagnitude > 0)
        {
            _dashDirection = _moveDirection;
        }
        else // If standing still, dash forward
        {
            _dashDirection = _transform.forward;
        }
    }
}

using UnityEngine;

public class PlayerMovement
{
    // --- Settings ---
    private readonly float _moveSpeed;
    private readonly float _accelerationTime;
    private readonly float _turnSmoothTime;

    // --- Dash Settings ---
    private readonly float _dashSpeed = 30f;
    private readonly float _dashDuration = 0.1f;
    private readonly float _dashCooldown = 1f;

    // --- References ---
    private readonly CharacterController _controller;
    private readonly Transform _transform;
    private readonly Transform _cameraTransform;

    // --- State ---
    private Vector3 _currentMoveVelocity;
    private Vector3 _velocityDamper; // Used for Vector3.SmoothDamp
    private float _turnSmoothVelocity; // Used for Mathf.SmoothDampAngle

    private float _dashCooldownTimer;
    private float _dashTimer;
    private bool _isDashing;
    private Vector3 _dashDirection;

    public PlayerMovement(CharacterController controller, Transform cameraTransform, float moveSpeed, float accelerationTime, float turnSmoothTime)
    {
        _controller = controller;
        _transform = controller.transform;
        _cameraTransform = cameraTransform;
        _moveSpeed = moveSpeed;
        _accelerationTime = accelerationTime;
        _turnSmoothTime = turnSmoothTime;
    }

    public void Tick()
    {
        Vector3 inputDirection = new Vector3(Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical")).normalized;

        HandleDashState(inputDirection);

        if (_isDashing)
        {
            _controller.Move(_dashDirection * _dashSpeed * Time.deltaTime);
            return;
        }

        HandleMovementAndRotation(inputDirection);
    }

    private void HandleMovementAndRotation(Vector3 inputDirection)
    {
        Vector3 targetVelocity;
        if (inputDirection.magnitude >= 0.1f)
        {
            // 1. Calculate target angle relative to camera
            float targetAngle = Mathf.Atan2(inputDirection.x, inputDirection.z) * Mathf.Rad2Deg + _cameraTransform.eulerAngles.y;

            // 2. Smoothly rotate player towards the target angle
            float smoothedAngle = Mathf.SmoothDampAngle(_transform.eulerAngles.y, targetAngle, ref _turnSmoothVelocity, _turnSmoothTime);
            _transform.rotation = Quaternion.Euler(0f, smoothedAngle, 0f);

            // 3. Create a directional vector from the smoothed angle
            Vector3 moveDirection = Quaternion.Euler(0f, smoothedAngle, 0f) * Vector3.forward;

            // 4. Set the target velocity for acceleration
            targetVelocity = moveDirection.normalized * _moveSpeed;
        }
        else
        {
            // 5. If no input, target velocity is zero for deceleration
            targetVelocity = Vector3.zero;
        }

        // 6. Apply smooth acceleration/deceleration to the current velocity
        _currentMoveVelocity = Vector3.SmoothDamp(_currentMoveVelocity, targetVelocity, ref _velocityDamper, _accelerationTime);

        // 7. Apply final movement
        _controller.Move(_currentMoveVelocity * Time.deltaTime);
    }

    private void HandleDashState(Vector3 inputDirection)
    {
        if (_dashCooldownTimer > 0) _dashCooldownTimer -= Time.deltaTime;
        if (_dashTimer > 0)
        {
            _dashTimer -= Time.deltaTime;
            if (_dashTimer <= 0) _isDashing = false;
        }

        if (Input.GetKeyDown(KeyCode.Space) && _dashCooldownTimer <= 0)
        {
            StartDash(inputDirection);
        }
    }

    private void StartDash(Vector3 inputDirection)
    {
        _isDashing = true;
        _dashCooldownTimer = _dashCooldown;
        _dashTimer = _dashDuration;

        if (inputDirection.magnitude >= 0.1f)
        {
            float targetAngle = Mathf.Atan2(inputDirection.x, inputDirection.z) * Mathf.Rad2Deg + _cameraTransform.eulerAngles.y;
            _dashDirection = Quaternion.Euler(0f, targetAngle, 0f) * Vector3.forward;
        }
        else
        {
            _dashDirection = _transform.forward;
        }
    }
}

using UnityEngine;

[RequireComponent(typeof(CharacterController))]
public class Player : MonoBehaviour
{
    [Header("Dependencies")]
    [SerializeField] private GameObject _bulletPrefab;
    [SerializeField] private Transform _firePoint;

    [Header("Movement Settings")]
    [Tooltip("Target movement speed.")]
    [SerializeField] private float moveSpeed = 7f;
    [Tooltip("Time it takes to reach full speed. Lower is faster.")]
    [SerializeField] private float accelerationTime = 0.1f;
    [Tooltip("Time it takes to turn. Lower is faster.")]
    [SerializeField] private float turnSmoothTime = 0.05f;

    private PlayerMovement _movement;
    private PlayerAiming _aiming;
    private PlayerShooting _shooting;

    void Awake()
    {
        var controller = GetComponent<CharacterController>();
        var mainCamera = Camera.main;

        if (mainCamera == null)
        {
            Debug.LogError("Main Camera is not found in the scene! Please tag your camera as 'MainCamera'.");
            return;
        }

        _movement = new PlayerMovement(controller, mainCamera.transform, moveSpeed, accelerationTime, turnSmoothTime);
        _aiming = new PlayerAiming(mainCamera, transform);
        _shooting = new PlayerShooting(transform, _firePoint, _bulletPrefab);
    }

    void Update()
    {
        if (_movement == null) return;

        _movement.Tick();
        _aiming.Tick();
        _shooting.Tick(_aiming.AimDirection);
    }
}

using UnityEngine;

public class PlayerMovement
{
    // --- Settings ---
    private readonly float _moveSpeed;
    private readonly float _accelerationTime;

    // --- Dash Settings ---
    private readonly float _dashSpeed = 30f;
    private readonly float _dashDuration = 0.1f;
    private readonly float _dashCooldown = 1f;

    // --- References ---
    private readonly CharacterController _controller;
    private readonly Transform _transform;
    private readonly Transform _cameraTransform;

    // --- State ---
    private Vector3 _currentMoveVelocity;
    private Vector3 _velocityDamper; // Used for Vector3.SmoothDamp

    private float _dashCooldownTimer;
    private float _dashTimer;
    private bool _isDashing;
    private Vector3 _dashDirection;

    public PlayerMovement(CharacterController controller, Transform cameraTransform, float moveSpeed, float accelerationTime)
    {
        _controller = controller;
        _transform = controller.transform;
        _cameraTransform = cameraTransform;
        _moveSpeed = moveSpeed;
        _accelerationTime = accelerationTime;
    }

    public void Tick()
    {
        Vector3 inputDirection = new Vector3(Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical"));

        HandleDashState(inputDirection);

        if (_isDashing)
        {
            _controller.Move(_dashDirection * _dashSpeed * Time.deltaTime);
            return;
        }

        HandleMovement(inputDirection);
    }

    private void HandleMovement(Vector3 inputDirection)
    {
        Vector3 targetVelocity;

        if (inputDirection.magnitude >= 0.1f)
        {
            // 1. Get camera's forward and right vectors, ignoring vertical tilt
            Vector3 camForward = _cameraTransform.forward;
            Vector3 camRight = _cameraTransform.right;
            camForward.y = 0;
            camRight.y = 0;
            camForward.Normalize();
            camRight.Normalize();

            // 2. Calculate world-space move direction based on camera and input
            Vector3 targetDirection = (camForward * inputDirection.z + camRight * inputDirection.x).normalized;

            // 3. Set target velocity for acceleration
            targetVelocity = targetDirection * _moveSpeed;
        }
        else
        {
            // 4. If no input, target velocity is zero for deceleration
            targetVelocity = Vector3.zero;
        }

        // 5. Apply smooth acceleration/deceleration
        _currentMoveVelocity = Vector3.SmoothDamp(_currentMoveVelocity, targetVelocity, ref _velocityDamper, _accelerationTime);

        // 6. Apply final movement
        _controller.Move(_currentMoveVelocity * Time.deltaTime);
    }

    private void HandleDashState(Vector3 inputDirection)
    {
        if (_dashCooldownTimer > 0) _dashCooldownTimer -= Time.deltaTime;
        if (_dashTimer > 0)
        {
            _dashTimer -= Time.deltaTime;
            if (_dashTimer <= 0) _isDashing = false;
        }

        if (Input.GetKeyDown(KeyCode.Space) && _dashCooldownTimer <= 0)
        {
            StartDash(inputDirection);
        }
    }

    private void StartDash(Vector3 inputDirection)
    {
        _isDashing = true;
        _dashCooldownTimer = _dashCooldown;
        _dashTimer = _dashDuration;

        if (inputDirection.magnitude >= 0.1f)
        {
            Vector3 camForward = _cameraTransform.forward;
            Vector3 camRight = _cameraTransform.right;
            camForward.y = 0;
            camRight.y = 0;
            camForward.Normalize();
            camRight.Normalize();
            _dashDirection = (camForward * inputDirection.z + camRight * inputDirection.x).normalized;
        }
        else
        {
            // If standing still, dash in the direction the player is currently facing
            _dashDirection = _transform.forward;
        }
    }
}

