    [Tooltip("Drag the TextMeshPro UI element for the dash cooldown here.")]
    [SerializeField] private TextMeshProUGUI _dashCooldownText;

    [Header("Movement Settings")]
    [SerializeField] private float moveSpeed = 7f;
    [SerializeField] private float accelerationTime = 0.1f;

    [Header("Impulse Shake Profiles")]
    [Tooltip("The shake profile for the dash action.")]
    [SerializeField] private NoiseSettings _dashShakeProfile;
    [Tooltip("The shake profile for shooting a weapon.")]
    [SerializeField] private NoiseSettings _gunshotShakeProfile;

    private PlayerMovement _movement;
    private PlayerAiming _aiming;
    private PlayerShooting _shooting;
    private CinemachineImpulseSource[] _impulseSources;

    void Awake()
    {
        var controller = GetComponent<CharacterController>();
        var mainCamera = Camera.main;
        _impulseSources = GetComponents<CinemachineImpulseSource>();

        if (mainCamera == null)
        {
            Debug.LogError("Main Camera is not found in the scene! Please tag your camera as 'MainCamera'.");
            return;
        }

        _movement = new PlayerMovement(controller, mainCamera.transform, moveSpeed, accelerationTime);
        _aiming = new PlayerAiming(mainCamera, transform);
        _shooting = new PlayerShooting(transform, _firePoint, _bulletPrefab);

        if (_dashCooldownText != null)
        {
            _dashCooldownText.gameObject.SetActive(false);
        }
    }

    void Update()
    {
        if (_movement == null) return;

        _movement.Tick();
        _aiming.Tick();
        _shooting.Tick(_aiming.AimDirection);

        if (_movement.JustDashed)
        {
            TriggerImpulse(_dashShakeProfile);
        }

        // Example: Trigger shake on mouse click.
        // You should integrate this with your actual shooting logic from PlayerShooting.
        if (Input.GetMouseButtonDown(0))
        {
            TriggerImpulse(_gunshotShakeProfile);
        }

        UpdateDashCooldownUI();
    }

    private void TriggerImpulse(NoiseSettings profile)
    {
        if (profile == null) return;

        foreach (var source in _impulseSources)
        {
            if (source.m_Signal == profile)
            {
                source.GenerateImpulse();
                return;
            }
        }
    }

    private void UpdateDashCooldownUI()
    {
        if (_dashCooldownText == null) return;

        float cooldown = _movement.DashCooldownTimer;
        if (cooldown > 0)
        {
            _dashCooldownText.gameObject.SetActive(true);
            _dashCooldownText.text = cooldown.ToString("F1");
        }
        else
        {
            _dashCooldownText.gameObject.SetActive(false);
        }
    }
}

