using UnityEngine;

public class PlayerAiming
{
    // --- Settings ---
    [Tooltip("The angle (in degrees) from the player's forward direction at which the whole body will start to turn.")]
    public float MaxAimAngle = 80f;

    // --- References ---
    private readonly Camera _cam;
    private readonly Transform _transform;

    // --- Public Properties ---
    public Vector3 AimDirection { get; private set; }
    public Vector3 AimPosition { get; private set; } // We expose this for the IK system

    public PlayerAiming(Camera cam, Transform transform)
    {
        _cam = cam;
        _transform = transform;
    }

    public void Tick()
    {
        // 1. Create a plane at the player's position to calculate the aim point
        Plane groundPlane = new Plane(Vector3.up, _transform.position);
        Ray ray = _cam.ScreenPointToRay(Input.mousePosition);

        if (groundPlane.Raycast(ray, out float enter))
        {
            AimPosition = ray.GetPoint(enter);
            AimDirection = (AimPosition - _transform.position).normalized;

            // 2. Calculate the angle between where the player is facing and where they are aiming
            float angle = Vector3.SignedAngle(_transform.forward, AimDirection, Vector3.up);

            // 3. Only turn the entire player body if the angle exceeds our threshold
            if (Mathf.Abs(angle) > MaxAimAngle)
            {
                // Smoothly rotate the body towards the aim direction
                Quaternion targetRotation = Quaternion.LookRotation(AimDirection);
                _transform.rotation = Quaternion.Slerp(_transform.rotation, targetRotation, Time.deltaTime * 15f);
            }
        }
    }
}

