// This special Unity function is called when IK Pass is enabled on an Animator layer
private void OnAnimatorIK(int layerIndex)
{
    if (_animator == null) return;

    // Set the weights for how much the body parts should follow the IK
    _animator.SetLookAtWeight(1f, _aimBodyWeight, _aimHeadWeight, 1f, 0.5f);

    // Get the pure horizontal direction from the aiming logic
    Vector3 aimDirection = _aiming.AimDirection;

    // --- THIS IS THE NEW, ROBUST SOLUTION ---
    // Get the current position of the character's head. This check prevents errors if the bone is not found.
    if (_animator.GetBoneTransform(HumanBodyBones.Head) == null) return;
    Vector3 headPosition = _animator.GetBoneTransform(HumanBodyBones.Head).position;

    // Create a new target point that is very far away in the correct direction.
    // This forces the IK to only care about the horizontal direction, not the distance or height.
    Vector3 lookAtTarget = headPosition + (aimDirection * 100f);

    // Tell the IK system to look at this new, distant, direction-based target
    _animator.SetLookAtPosition(lookAtTarget);
}

