// This class now calculates the aim direction FROM a specific origin point (e.g., the torso).
public class PlayerAiming
{
    private readonly Camera _cam;
    private readonly Transform _aimOrigin; // This will be the character's torso

    public Vector3 AimDirection { get; private set; }
    public Vector3 AimPosition { get; private set; }

    public PlayerAiming(Camera cam, Transform aimOrigin)
    {
        _cam = cam;
        _aimOrigin = aimOrigin;
    }

    public void Tick()
    {
        // The ground plane is still at the origin's Y position
        Plane groundPlane = new Plane(Vector3.up, _aimOrigin.position);
        Ray ray = _cam.ScreenPointToRay(Input.mousePosition);

        if (groundPlane.Raycast(ray, out float enter))
        {
            AimPosition = ray.GetPoint(enter);
            // THE CRITICAL CHANGE: We now calculate the direction from the torso, not the feet.
            AimDirection = (AimPosition - _aimOrigin.position).normalized;
        }
    }
}

