        _lastRotation = currentRotation;
    }

    private float ClampAndDamp(float value, float min, float max, ref float current, float damp)
    {
        value = Mathf.Clamp(value, min, max);
        return Mathf.Lerp(current, value, Time.deltaTime * damp);
    }

    private void UpdateAnimator()
    {
        if (_animator == null) return;
        Vector3 horizontalVelocity = new Vector3(_controller.velocity.x, 0, _controller.velocity.z);
